param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session "hq";$agency=Session "agency";$client=Session "client";$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/ai-sdr";$w=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh;$source=$w.sources|Select-Object -First 1;if(-not $source){throw "Missing unused independently verified ICP fit assessment"}
$lead=Post "$root/leads" @{assessment_id=$source.assessment_id} $hh;$recommendation=Post "$root/leads/$($lead.id)/recommendations" @{model_reference="approved-sdr-model-v1";prompt_reference="PRIVATE-SDR-PROMPT-$stamp";enrichment_summary="Verified ICP fit, buying trigger and business evidence support a human-reviewed discovery call.";intent_score=92;qualification_proposal="qualified";reply_subject="Production capacity evidence review";reply_body="We can review the verified capacity, delivery and ROI evidence with your buying team.";next_action="Book a 30-minute discovery workshop"} $hh;$reviewed=Post "$root/recommendations/$($recommendation.id)/review" @{expected_revision=$recommendation.revision;decision="approve";review_reference="SDR-HUMAN-QA-$stamp";review_note="Independently checked source evidence, qualification and reply wording"} $ah;$handoff=Post "$root/recommendations/$($reviewed.id)/handoff" @{owner_team="enterprise-sales";sla_minutes=30;delivery_reference="SALES-QUEUE-$stamp"} $ah;$ack=Post "$root/handoffs/$($handoff.id)/acknowledge" @{expected_revision=$handoff.revision;acknowledgement_reference="SALES-ACK-$stamp"} $ch;$w=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;lead_number=$lead.lead_number;recommendation_number=$reviewed.recommendation_number;handoff_number=$ack.handoff_number;manifest_hash=$ack.manifest_hash;fit_tier=$lead.fit_tier;intent_score=$reviewed.intent_score;human_review_percent=$w.metrics.human_review_percent;handoff_acknowledgement_percent=$w.metrics.handoff_acknowledgement_percent;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id;contract=$w.contract;metrics=$w.metrics}|ConvertTo-Json -Depth 8
